<script>
document.addEventListener('DOMContentLoaded',()=>{
 const pedido=new Map(), money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});let pending=null,timer,aborter;
 const list=document.getElementById('garcomOrderList'), hiddenBox=document.createElement('div');hiddenBox.id='garcomOrderInputs';document.getElementById('waForm').append(hiddenBox);
 const modal=document.getElementById('garcomObservacaoModal'), obs=document.getElementById('garcomObservacaoInput');
 const pizzaArea=document.getElementById('waPizzaOptions'),pizzaMode=document.getElementById('waPizzaModo'),secondFlavor=document.getElementById('waPizzaSabor2'),sizeField=document.getElementById('waPizzaSizeField'),sizeSelect=document.getElementById('waPizzaTamanho'),borderSelect=document.getElementById('waPizzaBorda'),secondField=document.getElementById('waPizzaSecondField'),sizeUnavailable=document.getElementById('waPizzaSizeUnavailable'),portionArea=document.getElementById('waPortionOptions'),portionType=document.getElementById('waTipoPorcao'),pricePreview=document.getElementById('waPersonalizationPrice'),confirmButton=document.getElementById('garcomObservacaoConfirmar');
 const readPrices=value=>{try{return JSON.parse(value||'{}')||{}}catch{return {}}};const readBorders=value=>{try{const result=JSON.parse(value||'[]');return Array.isArray(result)?result:[]}catch{return []}};
 function syncPersonalization(){if(!pending)return;const pizza=pending.tipo==='pizza',portion=pending.tipo==='porcao';pizzaArea.hidden=!pizza;portionArea.hidden=!portion;pizzaMode.disabled=!pizza;portionType.disabled=!portion;confirmButton.disabled=false;pending.personalizacao=null;pending.detail='';pending.displayName=pending.nome;let price=pending.basePrice;
  if(!pizza){secondFlavor.disabled=true;secondFlavor.required=false;sizeSelect.disabled=true;sizeSelect.required=false;borderSelect.disabled=true;borderSelect.required=false;borderSelect.value=''}
  if(pizza){
   borderSelect.disabled=false;borderSelect.required=true;
   const halfOption=pizzaMode.querySelector('option[value="meia_a_meia"]');halfOption.disabled=[...secondFlavor.options].filter(o=>o.value).length<2;if(halfOption.disabled&&pizzaMode.value==='meia_a_meia')pizzaMode.value='inteira';
   const half=pizzaMode.value==='meia_a_meia';secondField.hidden=!half;secondFlavor.disabled=!half;secondFlavor.required=half;[...secondFlavor.options].filter(o=>o.value).forEach(o=>o.disabled=o.value===pending.id);if(!half||secondFlavor.value===pending.id)secondFlavor.value='';
   const second=secondFlavor.selectedOptions[0],prices1=pending.prices||{},prices2=readPrices(second?.dataset.precos),borders1=pending.borders||[],borders2=readBorders(second?.dataset.bordas),availableBorders=half?borders1.filter(b=>borders2.some(other=>String(other.id)===String(b.id))):borders1;
   const previousBorder=borderSelect.value;borderSelect.replaceChildren(new Option('Escolha uma opção',''),new Option('Sem borda','0'));availableBorders.forEach(b=>borderSelect.add(new Option(b.nome,String(b.id))));if([...borderSelect.options].some(o=>o.value===previousBorder))borderSelect.value=previousBorder;
   const sizes1=Object.keys(prices1),sizes2=Object.keys(prices2),hasSizes=sizes1.length>0||(half&&sizes2.length>0),common=['P','M','G','GG','XG'].filter(size=>sizes1.includes(size)&&(!half||sizes2.includes(size))),previousSize=sizeSelect.value,slices={P:4,M:6,G:8,GG:10,XG:12};
   const selectedBorder=availableBorders.find(b=>String(b.id)===String(borderSelect.value));sizeSelect.replaceChildren(new Option('Selecione o tamanho',''));common.forEach(size=>{const p1=Number(prices1[size]||0),p2=half?Number(prices2[size]||0):0,base=half?Math.max(p1,p2):p1,extra=Number(selectedBorder?.adicionais_por_tamanho?.[size]||0),borderLabel=selectedBorder?`com ${selectedBorder.nome}`:'sem borda';sizeSelect.add(new Option(`${size} (${slices[size]} fatias) — ${money(base+extra)} ${borderLabel}`,size))});sizeSelect.disabled=common.length===0||!borderSelect.value;sizeSelect.required=common.length>0&&!!borderSelect.value;if(common.includes(previousSize))sizeSelect.value=previousSize;sizeField.hidden=common.length===0||!borderSelect.value;
   const incompatible=half&&!!second?.value&&hasSizes&&common.length===0;sizeUnavailable.hidden=!incompatible;const size=sizeSelect.value,missingSecond=half&&!second?.value,missingSize=hasSizes&&!size,missingBorder=!borderSelect.value;
   if(incompatible||missingSecond||missingBorder||missingSize){confirmButton.disabled=true;pricePreview.textContent=incompatible?'Os sabores escolhidos não têm um tamanho em comum cadastrado.':missingSecond?'Escolha o segundo sabor para calcular o preço.':missingBorder?'Escolha a borda antes do tamanho.':'Selecione o tamanho da pizza.'}
   else{const p1=size?Number(prices1[size]||0):pending.basePrice,p2=size?Number(prices2[size]||0):Number(second?.dataset.preco||0),base=half?Math.max(p1,p2):p1,border=availableBorders.find(b=>String(b.id)===String(borderSelect.value)),extra=size?Number(border?.adicionais_por_tamanho?.[size]||0):0;price=base+extra;pricePreview.textContent=`Preço unitário: ${money(price)} · ${border?`${border.nome} (+${money(extra)})`:'Sem borda'}${half?' (maior preço entre os sabores)':''}.`}
   pending.personalizacao={tipo:'pizza',modo:pizzaMode.value,...(size?{tamanho:size}:{}),borda_id:borderSelect.value,...(half&&second?.value?{sabor_2_id:second.value}:{})};pending.displayName=size?`Pizza ${size}`:'Pizza';pending.detail=half&&second?.value?`1/2 ${pending.nome} · 1/2 ${second.textContent.trim()}`:`Sabor: ${pending.nome}`;pending.detail+=` · ${availableBorders.find(b=>String(b.id)===String(borderSelect.value))?.nome||'Sem borda'}`;pending.preco=price;return}
  if(portion){const half=portionType.value==='meia',halfOption=portionType.querySelector('option[value="meia"]');halfOption.disabled=!pending.acceptsHalf;if(half&&!pending.acceptsHalf){confirmButton.disabled=true}else if(half)price=pending.halfPrice;pending.personalizacao={tipo:'porcao',tipo_porcao:half?'meia':'inteira'};pending.detail=half?'Meia porção':'Porção inteira';pricePreview.textContent=`Preço unitário: ${money(price)}.`;pending.preco=price;return}pricePreview.textContent='';pending.preco=price}
 function render(){list.innerHTML='';hiddenBox.innerHTML='';let total=0,count=0,i=0;pedido.forEach(item=>{total+=item.preco*item.quantidade;count+=item.quantidade;const row=document.createElement('div');row.className='garcom-order-item';const info=document.createElement('div');info.className='garcom-order-item__info';const name=document.createElement('strong');name.textContent=item.displayName||item.nome;const price=document.createElement('small');price.textContent=`${money(item.preco)} cada`;info.append(name,price);if(item.detail){const d=document.createElement('small');d.textContent=item.detail;info.append(d)}if(item.observacao){const o=document.createElement('small');o.className='garcom-order-item__observacao';o.textContent='Obs.: '+item.observacao;info.append(o)}const controls=document.createElement('div');controls.className='garcom-order-item__controls';const btn=(text,act)=>{const b=document.createElement('button');b.type='button';b.className=act==='remove'?'garcom-order-remove':'garcom-order-icon-btn';b.textContent=text;b.dataset.act=act;b.dataset.key=item.key;return b};const q=document.createElement('input');q.type='number';q.min='1';q.max='99';q.value=item.quantidade;q.className='garcom-order-qtd';q.dataset.qty=item.key;controls.append(btn('−','dec'),q,btn('+','inc'),btn('Remover','remove'));row.append(info,controls);list.append(row);[['produto_id',item.id],['quantidade',item.quantidade],['observacao',item.observacao]].forEach(([field,value])=>{const input=document.createElement('input');input.type='hidden';input.name=`itens[${i}][${field}]`;input.value=value;hiddenBox.append(input)});Object.entries(item.personalizacao||{}).forEach(([field,value])=>{if(value!==null&&value!==''){const input=document.createElement('input');input.type='hidden';input.name=`itens[${i}][personalizacao][${field}]`;input.value=value;hiddenBox.append(input)}});i++});document.getElementById('garcomOrderEmpty').hidden=pedido.size>0;document.getElementById('garcomOrderTotal').textContent=money(total);document.getElementById('garcomOrderCount').textContent=`${count} ${count===1?'item':'itens'}`;const disabled=!pedido.size;document.getElementById('garcomLimparPedido').disabled=disabled;document.getElementById('garcomEnviarPedido').disabled=disabled;document.getElementById('waSubmitBottom').disabled=disabled}
 function addPending(observation){if(!pending)return;const personalization=pending.personalizacao||{},key=JSON.stringify([pending.id,personalization,observation]),old=pedido.get(key);if(old)old.quantidade=Math.min(99,old.quantidade+pending.quantidade);else pedido.set(key,{...pending,key,observacao:observation});pending=null;obs.value='';modal.close();render()}
 document.querySelectorAll('[data-garcom-add]').forEach(b=>b.addEventListener('click',()=>{const tr=b.closest('tr'),q=tr.querySelector('[data-garcom-qtd]'),price=Number(tr.dataset.produtoPreco)||0;pending={id:tr.dataset.produtoId,nome:tr.dataset.produtoNome,tipo:tr.dataset.produtoTipo||'',preco:price,basePrice:price,halfPrice:Number(tr.dataset.precoMeia)||0,acceptsHalf:tr.dataset.aceitaMeia==='1',prices:readPrices(tr.dataset.precos),borders:readBorders(tr.dataset.bordas),quantidade:Math.min(99,Math.max(1,Number(q.value)||1))};pizzaMode.value='inteira';secondFlavor.value='';sizeSelect.value='';borderSelect.value='';portionType.value='inteira';const half=portionType.querySelector('option[value="meia"]');half.disabled=!pending.acceptsHalf;half.textContent=pending.acceptsHalf?`Meia porção — ${money(pending.halfPrice)}`:'Meia porção — indisponível';syncPersonalization();document.getElementById('garcomObservacaoProduto').textContent=`${pending.quantidade}x ${pending.nome}`;obs.value='';modal.showModal()}));
 modal.querySelector('form').addEventListener('submit',e=>{e.preventDefault();if(!pending||confirmButton.disabled)return;addPending(obs.value.trim())});
 document.getElementById('garcomObservacaoSem').addEventListener('click',()=>{pending=null;modal.close()});
 [pizzaMode,secondFlavor,sizeSelect,borderSelect,portionType].forEach(field=>field.addEventListener('change',syncPersonalization));
 list.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b)return;const item=pedido.get(b.dataset.key);if(b.dataset.act==='inc')item.quantidade=Math.min(99,item.quantidade+1);if(b.dataset.act==='dec')item.quantidade--;if(b.dataset.act==='remove'||item.quantidade<1)pedido.delete(item.key);render()});list.addEventListener('change',e=>{const input=e.target.closest('[data-qty]');if(!input)return;const item=pedido.get(input.dataset.qty);item.quantidade=Math.max(1,Math.min(99,Number(input.value)||1));render()});document.getElementById('garcomLimparPedido').addEventListener('click',()=>{pedido.clear();render()});
 const search=document.getElementById('searchInput'), category=document.getElementById('categoria_id'), rows=[...document.querySelectorAll('#tableBody tr')];function filter(){const q=search.value.trim().toLowerCase();rows.forEach(row=>{row.hidden=!(row.dataset.produtoNome.toLowerCase().includes(q)&&(!category.value||category.value===row.dataset.categoriaId))})}search.addEventListener('input',filter);category.addEventListener('change',filter);document.getElementById('limparFiltros').addEventListener('click',()=>{search.value='';category.value='';filter()});
 const phone=document.getElementById('telefone'),status=document.getElementById('buscaStatus'),userId=document.getElementById('usuario_id'),address=document.getElementById('endereco_id'),toggle=document.getElementById('addressCreateToggle'),check=document.getElementById('cadastrar_endereco'),newAddress=document.getElementById('novoEndereco'),addAddress=document.getElementById('addAddressButton'),editAddress=document.getElementById('editAddressButton'),replacementId=document.getElementById('substituir_endereco_id'),addressTitle=document.getElementById('novoEnderecoTitulo'),replacementNotice=document.getElementById('avisoSubstituirEndereco'),newCustomer=document.getElementById('novoClienteWrap'),customerName=document.getElementById('cliente_nome');
 const tipoEntrega=document.getElementById('tipo_entrega');document.querySelectorAll('[name="tipo_entrega_opcao"]').forEach(option=>option.addEventListener('change',()=>{tipoEntrega.value=option.value;tipoEntrega.dispatchEvent(new Event('change',{bubbles:true}))}));
 function mascaraTelefone(valor){let digitos=valor.replace(/\D/g,'');const internacional=digitos.length>11&&digitos.startsWith('55');if(internacional)digitos=digitos.slice(2);digitos=digitos.slice(0,11);let formatado=digitos;if(digitos.length>2){const ddd=digitos.slice(0,2),numero=digitos.slice(2);formatado=`(${ddd}) ${numero.length>8?numero.slice(0,5)+'-'+numero.slice(5):numero.length>4?numero.slice(0,4)+'-'+numero.slice(4):numero}`}return (internacional?'+55 ':'')+formatado}
 phone.value=mascaraTelefone(phone.value);phone.addEventListener('input',()=>{const pos=phone.selectionStart,anterior=phone.value;phone.value=mascaraTelefone(anterior);const delta=phone.value.length-anterior.length;phone.setSelectionRange(Math.max(0,pos+delta),Math.max(0,pos+delta))});
 function limparCamposEndereco(){['logradouro','numero','bairro','complemento'].forEach(id=>document.getElementById(id).value='');document.getElementById('cidade_id').value=''}
 function addressMode(){const isDelivery=tipoEntrega.value==='entrega',creating=check.checked&&isDelivery,editing=Boolean(replacementId.value);newAddress.classList.toggle('is-visible',creating);address.disabled=creating;address.required=isDelivery&&!creating;['logradouro','bairro','cidade_id'].forEach(id=>document.getElementById(id).required=creating);addressTitle.textContent=editing?'Alterar endereço cadastrado':'Novo endereço';replacementNotice.hidden=!editing;addAddress.hidden=editing;editAddress.hidden=!editing&&!address.value;editAddress.textContent=editing?'Cancelar edição':'Editar endereço'}
 check.addEventListener('change',()=>{if(!check.checked&&!replacementId.value)limparCamposEndereco();addressMode()});
 addAddress.addEventListener('click',()=>{check.checked=!check.checked;if(!check.checked)limparCamposEndereco();addressMode();if(check.checked&&tipoEntrega.value==='entrega')document.getElementById('logradouro').focus()});
 editAddress.addEventListener('click',()=>{if(replacementId.value){replacementId.value='';check.checked=false;limparCamposEndereco();addressMode();return}const selected=address.selectedOptions[0];if(!selected?.value)return;replacementId.value=selected.value;check.checked=true;document.getElementById('logradouro').value=selected.dataset.logradouro||'';document.getElementById('numero').value=selected.dataset.numero||'';document.getElementById('bairro').value=selected.dataset.bairro||'';document.getElementById('complemento').value=selected.dataset.complemento||'';document.getElementById('cidade_id').value=selected.dataset.cidadeId||'';addressMode();document.getElementById('logradouro').focus()});
 address.addEventListener('change',addressMode);
 tipoEntrega.addEventListener('change',()=>{document.getElementById('enderecoWrap').hidden=tipoEntrega.value!=='entrega';document.getElementById('tipo_pagamento_id').required=tipoEntrega.value==='entrega';if(tipoEntrega.value!=='entrega'&&check.checked){check.checked=false;replacementId.value='';limparCamposEndereco()}addressMode()});
 phone.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(async()=>{userId.value='';replacementId.value='';toggle.hidden=true;addAddress.hidden=true;editAddress.hidden=true;check.checked=false;limparCamposEndereco();addressMode();document.getElementById('clienteEncontrado').hidden=true;newCustomer.hidden=true;customerName.required=false;address.innerHTML='<option value="">Busque um cliente primeiro</option>';if(phone.value.replace(/\D/g,'').length<8){status.textContent='Digite o telefone para buscar o cadastro.';return}status.textContent='Buscando cliente…';aborter?.abort();aborter=new AbortController();try{const r=await fetch(`{{ route('admin.pedidos.whatsapp.cliente') }}?telefone=${encodeURIComponent(phone.value)}`,{headers:{Accept:'application/json'},signal:aborter.signal}),data=await r.json();if(!data.encontrado){status.textContent='Cliente não encontrado. Informe o nome para cadastrá-lo.';newCustomer.hidden=false;customerName.required=true;toggle.hidden=false;addAddress.hidden=false;address.innerHTML='<option value="">Novo endereço</option>';check.checked=true;addressMode();return}userId.value=data.cliente.id;status.textContent='Cliente localizado.';const badge=document.getElementById('clienteEncontrado');badge.textContent=`${data.cliente.nome} · ${data.cliente.telefone}`;badge.hidden=false;address.innerHTML='<option value="">Selecione um endereço</option>';data.enderecos.forEach(a=>{const o=document.createElement('option');o.value=a.id;o.textContent=a.label;o.dataset.logradouro=a.logradouro||'';o.dataset.numero=a.numero||'';o.dataset.bairro=a.bairro||'';o.dataset.complemento=a.complemento||'';o.dataset.cidadeId=a.cidade_id||'';address.append(o)});toggle.hidden=false;newCustomer.hidden=true;customerName.required=false;addAddress.hidden=false;if(!data.enderecos.length){check.checked=true;status.textContent='Cliente sem endereço salvo. Preencha o novo endereço para entrega ou escolha retirada.'}addressMode()}catch(e){if(e.name!=='AbortError')status.textContent='Não foi possível consultar o telefone.'}},350)});
 document.getElementById('waForm').addEventListener('submit',e=>{if(!userId.value&&!customerName.value.trim()){e.preventDefault();status.textContent='Informe o nome do novo cliente.';customerName.focus();return}if(!pedido.size){e.preventDefault();alert('Adicione pelo menos um produto ao pedido.')}});
 document.getElementById('enderecoWrap').hidden=document.getElementById('tipo_entrega').value!=='entrega';document.getElementById('tipo_pagamento_id').required=document.getElementById('tipo_entrega').value==='entrega';addressMode();render();
});
